import {VID,PID,USAGE_PAGE,USAGE,REPORT_ID,COMMAND,encodeCommand,decodeReport,isController} from './protocol.js';
const $=id=>document.getElementById(id);
const names=['Left A','Right A','Left B','Right B','Left C','Right C'];
// Keep raw channel order; expose the verified IO4 words/bits rather than guessing height numbers.
const mapping=['IO4 W1 · BIT 12','IO4 W0 · BIT 11','IO4 W1 · BIT 11','IO4 W0 · BIT 12','IO4 W1 · BIT 13','IO4 W0 · BIT 13'];
let device=null,state=null,lastReport=0,sequence=0,pending=null,heartbeat=null,brightnessTimer=null,brightnessDirty=false,triggerDirty=false,connecting=false,calStarted=0,epoch=0;
const tuningDrafts=names.map(()=>null);
const histories=names.map(()=>[]);const rows=[];
for(let i=0;i<6;i++){
 const row=document.createElement('article');row.className='sensor';row.innerHTML=`<div><div class="channel-label">${String(i+1).padStart(2,'0')} / ${mapping[i]}</div><h3 class="channel-name">${names[i]}</h3><div class="channel-state">AWAITING SIGNAL</div></div><canvas role="img" aria-label="${names[i]} live ADC trace"></canvas><div class="reading"><div class="adc-value"><span>—</span> <small>ADC</small></div><div class="thresholds"><span>BASE <b data-field="baseline">—</b></span><span class="trigger">TRIG ≤ <b data-field="trigger">—</b></span><span>REL &gt; <b data-field="release">—</b></span></div></div>`;$('sensors').append(row);rows.push(row);
}
for(let i=0;i<31;i++)$('led-strip').append(document.createElement('i'));
function notice(text,type=''){ $('notice').textContent=text;$('notice').className='notice '+type; }
function showBrightness(value){$('brightness-value').textContent=value;$('brightness').value=value;$('brightness').style.setProperty('--fill',`${value}%`);[...$('led-strip').children].forEach((led,i)=>led.style.opacity=i<Math.round(value*31/100)?'.9':'.15');}
function live(){return !!device&&lastReport>0&&Date.now()-lastReport<1800;}
function controls(){const online=live();rows.forEach(row=>{row.querySelectorAll('.channel-tuning input').forEach(e=>e.disabled=!online||!state?.perChannel||state?.calibration===1||!!(state?.flags&4));row.querySelector('.apply-channel').disabled=!online||!state?.perChannel||!!pending||state?.calibration===1||!!(state?.flags&4);});$('trigger-percent').disabled=!online||!!(state?.flags&4);$('apply-trigger').disabled=$('trigger-percent').disabled||!!pending;$('brightness').disabled=!online||!!pending||!!(state?.flags&4);$('calibrate').disabled=!online||!!pending||state?.calibration===1||!!(state?.flags&4);$('save').disabled=!online||!!pending||state?.calibration!==2||!(state?.flags&2);$('connect').disabled=connecting;}
function draw(i){const canvas=rows[i].querySelector('canvas'),r=canvas.getBoundingClientRect(),dpr=window.devicePixelRatio||1;if(r.width===0)return;canvas.width=Math.round(r.width*dpr);canvas.height=Math.round(r.height*dpr);const ctx=canvas.getContext('2d');ctx.scale(dpr,dpr);const w=r.width,h=r.height,y=v=>h-4-v/4095*(h-8);if(state){for(const [value,color,dash]of [[state.channels[i].trigger,'#ffa1d9',[4,4]],[state.channels[i].release,'#aab4ff',[1,4]]]){ctx.strokeStyle=color;ctx.setLineDash(dash);ctx.beginPath();ctx.moveTo(0,y(value));ctx.lineTo(w,y(value));ctx.stroke();}}const values=histories[i];ctx.setLineDash([]);ctx.lineWidth=1.8;ctx.strokeStyle=state?.channels[i].blocked?'#ffa1d9':'#d9ff79';ctx.beginPath();values.forEach((v,n)=>{const x=w-(values.length-1-n)*w/119;n?ctx.lineTo(x,y(v)):ctx.moveTo(x,y(v));});ctx.stroke();}
function render(next){if(next.triggerPercent&&!triggerDirty&&document.activeElement!==$('trigger-percent'))$('trigger-percent').value=next.triggerPercent;$('trigger-state').textContent=next.triggerPercent?`${next.triggerPercent}% active · resets to 12% on restart`:'Individual tuning active · resets on restart';const priorCalibration=state?.calibration;if(priorCalibration===1&&next.calibration===2)notice('Calibration complete. New thresholds are active; save them to keep them after power-off.','success');if(priorCalibration===1&&next.calibration===3)notice('Calibration failed. Previous thresholds remain active. Check the towers and try again.','error');state=next;lastReport=Date.now();$('connection-state').textContent='CONNECTED';$('connection-state').className='status online';$('sample-rate').textContent='LIVE / 20 HZ';$('firmware-state').textContent='PROTOCOL '+next.version;$('snapshot-id').textContent='FRAME '+String(next.sampleId).padStart(5,'0');$('beam-summary').textContent=next.channels.filter(c=>c.blocked).length+' / 6 BLOCKED';$('power-cap').textContent=next.powerCap+' mA';$('trigger-info').textContent=`${next.triggerPercent?next.triggerPercent+'% DROP':'INDIVIDUAL TRIGGERS'} / ${next.hysteresis}% HYSTERESIS`;if(!brightnessDirty)showBrightness(next.brightness);
 next.channels.forEach((c,i)=>{const row=rows[i];row.className='sensor '+(c.blocked?'blocked':'clear');row.querySelector('.channel-state').textContent=c.blocked?'BEAM BLOCKED':'BEAM CLEAR';row.querySelector('.adc-value span').textContent=c.raw;for(const field of ['baseline','trigger','release'])row.querySelector(`[data-field="${field}"]`).textContent=c[field];renderTuning(i,c);histories[i].push(c.raw);if(histories[i].length>120)histories[i].shift();draw(i);});
 if(next.calibration===1){if(!calStarted)calStarted=Date.now();$('cal-state').textContent='Capturing clear beams… keep all six unobstructed.';$('cal-progress').style.width=Math.min(95,(Date.now()-calStarted)/2000*100)+'%';}
 else{calStarted=0;$('cal-progress').style.width=next.calibration===2?'100%':'0';$('cal-state').textContent=next.calibration===3?'Capture rejected: one or more signals are too low. Check the towers and try again.':next.flags&2?'New calibration active · not saved to flash':next.flags&1?'Saved calibration loaded':'Default baselines · calibration recommended';}
 if(next.flags&4){notice('Saving calibration. The controller is restarting; reconnect when it returns.');$('cal-state').textContent='Restarting to save calibration…';}
 else if(next.flags&8)notice('Calibration save failed. Check the reported baselines and calibrate again.','error');
 if(pending&&next.sequence===pending.sequence&&next.command===pending.command){const p=pending;pending=null;clearTimeout(p.timeout);if(next.result!==0)p.reject(new Error(['','Command rejected','Controller is busy','Calibrate successfully before saving','Calibration save failed'][next.result]||'Controller error'));else p.resolve(next);}
 controls();}
function input(event){if(event.device!==device||event.reportId!==REPORT_ID)return;try{render(decodeReport(event.data));}catch(error){notice(error.message,'error');}}
async function command(code,value=0,channel=0){if(!device?.opened)throw new Error('Connect the controller first.');if(pending)throw new Error('A controller command is still pending.');const target=device;sequence=sequence%65535+1;const seq=sequence;return new Promise((resolve,reject)=>{pending={sequence:seq,command:code,resolve,reject,timeout:setTimeout(()=>{if(pending?.sequence===seq){pending=null;controls();reject(new Error('The controller did not respond. Reconnect it and check the WebHID firmware.'));}},2000)};controls();target.sendReport(REPORT_ID,encodeCommand(code,seq,value,channel)).catch(error=>{if(pending?.sequence===seq){clearTimeout(pending.timeout);pending=null;controls();reject(error);}});});}
async function disconnect(message='Controller disconnected. Readings are paused.'){
 epoch++;tuningDrafts.fill(null);triggerDirty=false;clearInterval(heartbeat);clearTimeout(brightnessTimer);heartbeat=null;brightnessTimer=null;brightnessDirty=false;
 if(pending){clearTimeout(pending.timeout);pending.reject(new Error('Controller disconnected'));pending=null;}
 const previous=device;device=null;lastReport=0;state=null;previous?.removeEventListener('inputreport',input);if(previous?.opened)try{await previous.close();}catch{}
 $('connection-state').textContent='OFFLINE';$('connection-state').className='status';$('connect').innerHTML='Connect controller <span>＋</span>';$('sample-rate').textContent='NO SIGNAL';$('beam-summary').textContent='6 CHANNELS';$('cal-state').textContent='Waiting for controller';$('trigger-state').textContent='1–99% · default 12% · resets on restart';$('cal-progress').style.width='0';$('brightness-value').textContent='—';$('snapshot-id').textContent='FRAME —';$('firmware-state').textContent='PROTOCOL —';histories.forEach(h=>h.length=0);rows.forEach((r,i)=>{r.className='sensor';r.querySelector('.channel-state').textContent='AWAITING SIGNAL';r.querySelector('.adc-value span').textContent='—';r.querySelectorAll('[data-field]').forEach(e=>e.textContent='—');draw(i);});notice(message);controls();}
$('connect').addEventListener('click',async()=>{
 if(device){await disconnect();return;}connecting=true;controls();const currentEpoch=++epoch;
 try{
  const devices=await navigator.hid.requestDevice({filters:[{vendorId:VID,productId:PID,usagePage:USAGE_PAGE,usage:USAGE}]});
  const chosen=devices.find(isController);if(!chosen){notice('No controller selected. Install the WebHID UF2 if the controller is missing.');return;}
  await chosen.open();if(epoch!==currentEpoch){await chosen.close();return;}device=chosen;device.addEventListener('inputreport',input);$('connect').innerHTML='Disconnect <span>×</span>';notice('Reading controller…');await command(COMMAND.subscribe);if(!(state?.flags&8))notice('Controller connected. Sensor values and thresholds are live.','success');
  heartbeat=setInterval(async()=>{if(!device||pending||brightnessDirty)return;try{await command(COMMAND.subscribe);}catch(e){notice(e.message,'error');}},1000);
 }catch(error){await disconnect('Connection failed: '+error.message);$('notice').classList.add('error');}finally{connecting=false;controls();}
});
$('brightness').addEventListener('input',()=>{const value=Number($('brightness').value);brightnessDirty=true;showBrightness(value);clearTimeout(brightnessTimer);const currentEpoch=epoch;brightnessTimer=setTimeout(async()=>{try{await command(COMMAND.brightness,value);$('brightness-state').textContent=`${value}% applied · resets on restart`;}catch(error){notice(error.message,'error');}finally{if(epoch===currentEpoch){brightnessDirty=false;if(state)showBrightness(state.brightness);controls();}}},160);});
$('trigger-percent').addEventListener('input',()=>{triggerDirty=true;});
$('trigger-form').addEventListener('submit',async event=>{event.preventDefault();const draft=$('trigger-percent').value;const currentEpoch=epoch;try{await command(COMMAND.trigger,Number(draft));if(epoch===currentEpoch&&$('trigger-percent').value===draft)triggerDirty=false;notice('IR trigger update accepted. Live thresholds show the applied setting.','success');}catch(error){notice(error.message,'error');}});
$('calibrate').addEventListener('click',async()=>{try{await command(COMMAND.calibrate);notice('Calibration started. Keep every beam clear for two seconds.');}catch(error){notice(error.message,'error');}});
$('save').addEventListener('click',()=>$('save-dialog').showModal());
$('save-dialog').addEventListener('close',async()=>{if($('save-dialog').returnValue!=='save')return;try{await command(COMMAND.save);}catch(error){notice(error.message,'error');}});
navigator.hid?.addEventListener('disconnect',event=>{if(event.device===device)void disconnect(state?.flags&4?'Controller restarted. Press Connect controller to verify the saved calibration.':undefined);});
window.addEventListener('resize',()=>rows.forEach((_,i)=>draw(i)));
setInterval(()=>{if(device&&lastReport&&Date.now()-lastReport>=1800){$('connection-state').textContent='STALE';$('connection-state').className='status';$('sample-rate').textContent='SIGNAL PAUSED';notice('Live readings stopped. Reconnect the controller if they do not resume.','error');controls();}},500);
if(!window.isSecureContext||!navigator.hid){$('connect').disabled=true;notice('WebHID is unavailable here. Open this page in desktop Chrome or Edge using localhost or HTTPS.','error');}
// Optional page-scoped agent access is read-only: hardware commands stay behind the visible controls.
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'read_controller_state',description:'Read the connected controller’s live air values, thresholds and brightness. Does not send commands.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({connected:live(),state:live()?state:null})})).catch(()=>{});}catch{}}

// Draft values survive telemetry, focus changes and heartbeat acknowledgements.
for (let i=0;i<6;i++) {
 const form=document.createElement('form');form.className='channel-tuning';
 form.innerHTML=`<label for="sensitivity-${i}">Sensitivity <output class="drop-label"></output></label><input id="sensitivity-${i}" class="sensitivity" type="range" min="1" max="99" value="88" disabled><div class="range-labels"><span>LESS SENSITIVE</span><span>MORE SENSITIVE</span></div><div class="threshold-edit"><label for="threshold-${i}">Trigger at or below ADC</label><input id="threshold-${i}" class="threshold-input" type="number" min="0" max="4094" required disabled><button class="secondary apply-channel" disabled>Apply ${names[i]}</button></div><p class="fine tuning-status">Connect the updated firmware to tune this receiver.</p>`;
 rows[i].append(form);
 const slider=form.querySelector('.sensitivity'),input=form.querySelector('.threshold-input');
 slider.addEventListener('input',()=>{const drop=100-Number(slider.value),base=state.channels[i].baseline;tuningDrafts[i]={mode:6,value:drop};input.value=base-Math.floor(base*drop/100);form.querySelector('.drop-label').textContent=`${drop}% drop`;form.querySelector('.tuning-status').textContent='Preview only · press Apply';});
 input.addEventListener('input',()=>{const value=Number(input.value),base=state.channels[i].baseline;tuningDrafts[i]={mode:7,value};slider.value=Math.max(1,Math.min(99,100-(base-value)*100/base));form.querySelector('.drop-label').textContent=`${((base-value)*100/base).toFixed(1)}% drop`;form.querySelector('.tuning-status').textContent='Preview only · press Apply';});
 form.addEventListener('submit',async e=>{e.preventDefault();const draft=tuningDrafts[i];if(!draft)return;const currentEpoch=epoch;try{if(draft.mode===7&&draft.value>=state.channels[i].baseline)throw new Error('Trigger must be below this receiver’s baseline.');await command(draft.mode,draft.value,i);if(epoch===currentEpoch&&tuningDrafts[i]===draft)tuningDrafts[i]=null;notice(`${names[i]} tuning accepted. Live thresholds show the applied setting.`,'success');}catch(error){notice(error.message,'error');}});
}
function renderTuning(i,c){const form=rows[i].querySelector('.channel-tuning');if(!form)return;if(tuningDrafts[i])return;const drop=c.baseline?(c.baseline-c.trigger)*100/c.baseline:12;form.querySelector('.sensitivity').value=Math.max(1,Math.min(99,100-drop));form.querySelector('.threshold-input').value=c.trigger;form.querySelector('.threshold-input').max=Math.max(0,c.baseline-1);form.querySelector('.drop-label').textContent=`${drop.toFixed(1)}% drop`;form.querySelector('.tuning-status').textContent=state.perChannel?(c.absolute?'Fixed ADC threshold':'Sensitivity follows calibrated baseline')+' · resets on restart':'Install the updated UF2 to enable individual tuning.';}
